import math

def cipher_text(plain_text):
    normalized = ''.join(ch.lower() for ch in plain_text if ch.isalnum())
    L = len(normalized)
    if L == 0:
        return ""
    r = int(math.floor(math.sqrt(L)))
    c = int(math.ceil(math.sqrt(L)))
    if r * c < L:
        r += 1
    chunks = []
    for i in range(c):
        col_chars = []
        for j in range(r):
            pos = j * c + i
            col_chars.append(normalized[pos] if pos < L else ' ')
        chunks.append(''.join(col_chars))
    return ' '.join(chunks)
